"""Shared export pipeline.

``export_rows`` is the single serialization entry point; the public
``export_csv`` and ``export_json`` wrappers (and the dispatcher) delegate to
it so normalization and formatting live in exactly one place.
"""

import csv
import io
import json

#: Row fields every export keeps, in output order.
FIELDS = ("id", "name")


def export_rows(rows, format):
    """Serialize ``rows`` as ``format`` ('csv' or 'json').

    Each row is reduced to its ``id`` and ``name`` values: missing or None
    become "", anything else is stringified. ``rows`` is read exactly once,
    so one-shot iterables work, and the row objects themselves are never
    mutated. Unsupported formats raise ``ValueError`` without reading rows.
    """
    if format == "csv":
        return _to_csv(_normalize(rows))
    if format == "json":
        return _to_json(_normalize(rows))
    raise ValueError("unsupported format")


def _normalize(rows):
    """Consume ``rows`` once into a list of ``{"id": ..., "name": ...}`` dicts."""
    return [{field: _field_value(row, field) for field in FIELDS} for row in rows]


def _field_value(row, field):
    value = row.get(field)
    return "" if value is None else str(value)


def _to_csv(normalized):
    buffer = io.StringIO(newline="")
    writer = csv.writer(buffer, lineterminator="\n")
    writer.writerow(FIELDS)
    for row in normalized:
        writer.writerow([row[field] for field in FIELDS])
    return buffer.getvalue()


def _to_json(normalized):
    return json.dumps(normalized, ensure_ascii=False, separators=(",", ":"))
